out=[]
for repo,records in sorted(rows.items()):
 retrieved=any(r.get('status')=='retrieved' or any(f.get('status')=='retrieved' for f in r.get('files',[])) for r in records)
 classification,note=notes.get(repo,('discovery only' if retrieved else 'unavailable/unverified','Snapshot retrieval is not a source audit or experimental validation.' if retrieved else 'Failed guessed or unavailable source retained; do not infer project existence or performance.'))
 out.append({'repository':repo,'url':'https://github.com/'+repo,'retrieved':retrieved,'review_level':classification,'assessment':note,'source_manifests':sorted({r['manifest'] for r in records}),'pins':sorted({r.get('head_commit',r.get('commit','')) for r in records if r.get('head_commit',r.get('commit'))})})
result={'as_of_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Bounded broad survey, not exhaustive market coverage; reviewed levels distinguish downloaded READMEs, source audits and actual experiments. No vendor claim is a measured improvement of our serving candidate.','counts':{'unique_repository_strings':len(out),'at_least_one_retrieved_file':sum(r['retrieved'] for r in out),'with_manual_assessment':len(notes)},'projects':out}
(p/'SOURCE_AUDIT.json').write_text(json.dumps(result,indent=2))
lines=['INFERENCE SOURCE AUDIT - ONGOING',result['scope'],'',json.dumps(result['counts']),'']
for r in out:lines.extend([r['repository']+' | '+r['review_level'],r['assessment'],r['url'],''])
